const jsInline = `// ==========================================================================
// database.js - MOTOR DE INTELIGÊNCIA COM ID DE 6 DÍGITOS
// ==========================================================================

const API_URL = "http://127.0.0.1:3000";

/**
 * 1. BUSCA DE DADOS NA REDE
 */
async function getRegistros() {
    try {
        const response = await axios.get(\`\${API_URL}/get-data\`);
        return response.data;
    } catch (error) {
        console.error("Erro ao ler banco compartilhado:", error);
        return [];
    }
}

/**
 * 2. SALVAR REGISTRO (O PROCESSO DE CARIMBO)
 */
async function salvarRegistro(dados) {
    try {
        // A. PROCV: Identifica o PH real no motor Node (120k itens)
        const resPH = await axios.get(\`\${API_URL}/get-ph?item=\${dados.item}\`);
        dados.ph = resPH.data.ph; 

        // B. Metadados do sistema
        dados.id = Date.now(); 
        dados.dataReg = dayjs().format('YYYY-MM-DD');

        // C. ANÁLISE PRÉVIA: Este registro vai disparar um alerta?
        const todos = await getRegistros();
        const resultadoAnalise = analisarStatusTecnico(dados, todos);

        if (resultadoAnalise.gerarAlerta) {
            // Se o grupo já tem um ID, usa o dele. Se é novo, pede um de 6 dígitos pro Node.
            if (resultadoAnalise.idExistente) {
                dados.alertaID = resultadoAnalise.idExistente;
            } else {
                const resID = await axios.get(\`\${API_URL}/gerar-id-alerta\`);
                dados.alertaID = resID.data.id;
            }

            // ============================================================
            // AJUSTE 2: O ALERTA VISUAL (O AVISO QUE PULA NA TELA)
            // ============================================================
            alert(
                \`🚨 REQUISITO DE QUALIDADE ATINGIDO!\\n\\n\` +
                \`ID DO ALERTA: #\${dados.alertaID}\\n\` + // Exibe o 202601
                \`----------------------------------------\\n\` +
                \`PH: \${dados.ph}\\n\` +
                \`Falha: \${dados.falha}\\n\` +
                \`Planta: \${dados.planta}\\n\\n\` +
                \`O registro foi vinculado a este processo oficial.\`
            );
        }

        // D. Gravação Final no Drive S:
        const resposta = await axios.post(\`\${API_URL}/save-data\`, dados);
        return resposta.data === "ok";

    } catch (error) {
        console.error("Erro no processo de salvamento:", error);
        return false;
    }
}

/**
 * 3. LÓGICA DE DECISÃO (TRÍADE)
 * Analisa se a inclusão deste novo item atinge as regras 1, 2 ou 3.
 */
function analisarStatusTecnico(novo, historico) {
    // Filtro por PH + Planta + Falha (A base do seu Requisito)
    const grupo = historico.filter(r => 
        r.ph === novo.ph && r.planta === novo.planta && r.falha === novo.falha
    );

    const m0 = dayjs(novo.dataFab).format('YYYY-MM');
    const m1 = dayjs(novo.dataFab).subtract(1, 'month').format('YYYY-MM');
    const m2 = dayjs(novo.dataFab).subtract(2, 'month').format('YYYY-MM');

    // Conta considerando o "+1" que estamos tentando salvar agora
    const n0 = grupo.filter(r => dayjs(r.dataFab).format('YYYY-MM') === m0).length + 1;
    const n1 = grupo.filter(r => dayjs(r.dataFab).format('YYYY-MM') === m1).length;
    const n2 = grupo.filter(r => dayjs(r.dataFab).format('YYYY-MM') === m2).length;

    // Critérios
    const crit1 = (n0 >= 3);
    const crit2 = (n0 >= 2 && n1 >= 2);
    const crit3 = (n0 >= 1 && n1 >= 1 && n2 >= 1);

    if (crit1 || crit2 || crit3) {
        // Busca se alguém do grupo já tem um ID oficial carimbado
        const registroComID = grupo.find(r => r.alertaID);
        return { 
            gerarAlerta: true, 
            idExistente: registroComID ? registroComID.alertaID : null 
        };
    }

    return { gerarAlerta: false };
}

/**
 * 4. ATUALIZAÇÃO DOS CARDS KPI (DASHBOARD)
 */
function atualizarCardsResumo(registros) {
    if (!registros) return;

    // Atualiza o contador de notificações totais
    const elTotal = document.getElementById('card-total');
    if (elTotal) elTotal.innerText = registros.length;

    // Conta quantos IDs de alerta ÚNICOS existem na base
    const idsUnicos = new Set();
    registros.forEach(r => {
        if (r.alertaID) idsUnicos.add(r.alertaID);
    });

    const elAlertas = document.getElementById('card-alertas');
    if (elAlertas) elAlertas.innerText = idsUnicos.size;

    // Identifica o Material (Item) mais reclamado
    const ranking = {};
    registros.forEach(r => ranking[r.item] = (ranking[r.item] || 0) + 1);
    const top = Object.entries(ranking).sort((a,b) => b[1]-a[1])[0];
    const elTop = document.getElementById('card-top');
    if (elTop) elTop.innerText = top ? top[0] : '-';
}

/**
 * 5. MANUTENÇÃO
 */
async function excluirUmRegistro(id) {
    const res = await axios.get(\`\${API_URL}/excluir-registro?id=\${id}\`);
    return res.data === "ok";
}

async function limparBancoDeDados() {
    const res = await axios.get(\`\${API_URL}/limpar-tudo\`);
    return res.data === "ok";
}

// ==========================================================================
// dashboard.js - VISUALIZAÇÃO ESTRATÉGICA E ANÁLISE DE DADOS (VERSÃO PN/PH)
// ==========================================================================

let charts = {}; // Gerenciador de instâncias para evitar erros de sobreposição

window.onload = async () => {
    console.log("Dashboard: Sincronizando dados e IDs oficiais da rede Bosch...");

    // 1. Busca os registros centralizados na rede (Drive S:)
    const registros = await getRegistros(); 

    // 2. Atualiza os cards superiores (KPIs) - Lógica de contagem oficial
    atualizarCardsResumo(registros);

    // 3. Renderiza os Gráficos (Tendência, Planta e Pareto)
    renderAllCharts(registros);

    // 4. Processa o Painel de Insights (Agrupamento por PH + Planta + Falha)
    renderInsights(registros);
};

/**
 * 1. PAINEL DE INSIGHTS - EXIBIÇÃO DOS ALERTAS COM ID DE 6 DÍGITOS
 */
function renderInsights(registros) {
    const container = document.getElementById('ai-insights-container');
    if (!container) return;

    if (!registros || registros.length === 0) {
        container.innerHTML = \`
            <div class="h-100 d-flex flex-column align-items-center justify-content-center text-muted opacity-40">
                <i class="fas fa-check-circle fa-4x mb-3 text-success"></i>
                <p class="fw-bold m-0">Operação Normal</p>
                <small>Nenhum registro encontrado na rede.</small>
            </div>\`;
        return;
    }

    // MAPA DE AGRUPAMENTO TÉCNICO (TRÍADE)
    const mapaAlertas = {};

    registros.forEach(r => {
        // Chave Mestra: Família + Planta + Erro (Agrupa materiais diferentes da mesma família)
        const chaveTríade = \`\${r.ph}_\${r.planta}_\${r.falha}\`;
        const mesFab = dayjs(r.dataFab).format('YYYY-MM');

        if (!mapaAlertas[chaveTríade]) {
            mapaAlertas[chaveTríade] = {
                ph: r.ph,
                planta: r.planta,
                falha: r.falha,
                alertaID: null, 
                mesesProducao: {},
                pnsAfetados: new Set(),
                totalGeral: 0
            };
        }

        mapaAlertas[chaveTríade].mesesProducao[mesFab] = (mapaAlertas[chaveTríade].mesesProducao[mesFab] || 0) + 1;
        mapaAlertas[chaveTríade].pnsAfetados.add(r.item);
        mapaAlertas[chaveTríade].totalGeral++;

        // Se encontrarmos o carimbo do ID em qualquer item do grupo, aplicamos ao card
        if (r.alertaID) {
            mapaAlertas[chaveTríade].alertaID = r.alertaID;
        }
    });

    let html = "";

    // FILTRAGEM: Apenas quem tem ID ou quem atingiu o critério de 3 itens
    const listaExibicao = Object.values(mapaAlertas)
        .filter(grupo => {
            const contagens = Object.values(grupo.mesesProducao);
            const atingiuLimite = contagens.some(qtd => qtd >= 3);
            return grupo.alertaID || atingiuLimite; 
        })
        .sort((a, b) => (b.alertaID || 0) - (a.alertaID || 0)); // Novos IDs no topo

    listaExibicao.forEach(grupo => {
        const idTexto = grupo.alertaID ? \`#\${grupo.alertaID}\` : "EM PROCESSAMENTO";

        html += \`
        <article class="ai-alert critical animate__animated animate__pulse animate__infinite">
            <div class="d-flex align-items-start gap-3">
                <div class="icon-bo"><i class="fas fa-exclamation-triangle fa-2x text-white"></i></div>
                <div class="flex-grow-1">
                    <div class="d-flex justify-content-between align-items-center mb-1">
                        <strong class="text-white" style="font-size: 1.1rem;">PN CRÍTICO: \${idTexto}</strong>
                        <span class="badge bg-white text-danger fw-bold" style="font-size: 0.65rem;">ALERTA OFICIAL</span>
                    </div>

                    <div class="mt-1 mb-2">
                        <span class="badge bg-dark bg-opacity-50 text-white py-2 px-3 w-100 text-start" style="font-size: 0.8rem; border: 1px solid rgba(255,255,255,0.2);">
                            <i class="fas fa-tools me-2"></i><b>FALHA:</b> \${grupo.falha}
                        </span>
                    </div>

                    <div class="small text-white-50" style="font-size: 0.75rem;">
                        <b>PH:</b> \${grupo.ph} | <b>Planta:</b> \${grupo.planta}
                    </div>

                    <div class="mt-2 p-2 bg-black bg-opacity-25 rounded" style="font-size: 0.7rem; color: #ffdada; line-height: 1.4;">
                        <b>PNs envolvidos:</b> \${Array.from(grupo.pnsAfetados).join(', ')}<br>
                        <b>Total de Reports:</b> \${grupo.totalGeral}
                    </div>
                </div>
            </div>
        </article>\`;
    });

    container.innerHTML = html || \`
        <div class="h-100 d-flex flex-column align-items-center justify-content-center text-muted opacity-40">
            <i class="fas fa-check-circle fa-4x mb-3 text-success"></i>
            <p class="fw-bold m-0">Operação Normal</p>
            <small>Nenhum alerta crítico detectado no momento.</small>
        </div>\`;
}

/**
 * 2. RENDERIZAÇÃO DOS GRÁFICOS (CHART.JS)
 */
function renderAllCharts(dados) {
    const config = { responsive: true, maintainAspectRatio: false, devicePixelRatio: 2 };

    // --- TENDÊNCIA (Últimos 6 meses baseados em dataReport) ---
    const mesesLabels = [];
    const valores = [];
    for (let i = 5; i >= 0; i--) {
        const d = dayjs().subtract(i, 'month');
        mesesLabels.push(d.format('MMM/YY'));
        const mesAno = d.format('YYYY-MM');
        valores.push(dados.filter(r => dayjs(r.dataReport).format('YYYY-MM') === mesAno).length);
    }
    createChart('trendChart', 'line', mesesLabels, [{
        label: 'Volume de Reclamações', 
        data: valores, 
        borderColor: '#0d6efd', 
        backgroundColor: 'rgba(13, 110, 253, 0.1)', 
        fill: true, 
        tension: 0.4
    }], config);

    // --- PLANTA INTELIGENTE (TOP 6 + OUTRAS) ---
    const plantasRaw = {};
    dados.forEach(r => { if(r.planta) plantasRaw[r.planta] = (plantasRaw[r.planta] || 0) + 1; });
    const pSorted = Object.entries(plantasRaw).sort((a,b) => b[1]-a[1]);

    let labelsP = pSorted.slice(0, 6).map(p => p[0]);
    let valoresP = pSorted.slice(0, 6).map(p => p[1]);

    if (pSorted.length > 6) {
        labelsP.push("Outras Plantas");
        valoresP.push(pSorted.slice(6).reduce((acc, curr) => acc + curr[1], 0));
    }

    createChart('plantChart', 'doughnut', labelsP, [{ 
        data: valoresP, 
        backgroundColor: ['#0d6efd', '#198754', '#ffc107', '#dc3545', '#6610f2', '#fd7e14', '#94a3b8'] 
    }], { 
        ...config, 
        cutout: '65%', 
        plugins: { 
            legend: { 
                position: 'right', 
                labels: { boxWidth: 12, font: { size: 10, weight: 'bold' } } 
            } 
        } 
    });

    // --- PARETO DE FALHAS (ORDENADO) ---
    const falhasRaw = {};
    dados.forEach(r => { if(r.falha) falhasRaw[r.falha] = (falhasRaw[r.falha] || 0) + 1; });
    const fSorted = Object.entries(falhasRaw).sort((a,b) => b[1]-a[1]);

    createChart('paretoChart', 'bar', fSorted.map(s => s[0]), [{ 
        label: 'Quantidade', 
        data: fSorted.map(s => s[1]), 
        backgroundColor: '#ffc107',
        borderRadius: 5
    }], { 
        ...config, 
        plugins: { legend: { display: false }}, 
        scales: { y: { beginAtZero: true, ticks: { stepSize: 1 } } } 
    });
}

/**
 * AUXILIAR: GESTÃO DE GRÁFICOS
 */
function createChart(id, type, labels, datasets, options) {
    if (charts[id]) charts[id].destroy(); 
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    charts[id] = new Chart(ctx, { type, data: { labels, datasets }, options });
}`;

